"use client"

import { Button } from "@/components/ai-elements/_ui/button"
import { Textarea } from "@/components/ai-elements/_ui/textarea"
import { cn } from "@/lib/utils"
import type {
  ChangeEvent,
  ComponentProps,
  FormEvent,
  HTMLAttributes,
  MouseEvent,
  ReactNode,
} from "react"
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react"

export interface QuestionValue {
  selectedValues: readonly string[]
  text: string
}

export interface QuestionResponse {
  selectedValues: readonly string[]
  text?: string
}

type SelectionMode = "multiple" | "single"

interface QuestionContextValue {
  disabled: boolean
  selectedValues: readonly string[]
  selectionMode: SelectionMode
  setText: (text: string) => void
  text: string
  toggleValue: (value: string) => void
}

const QuestionContext = createContext<QuestionContextValue | null>(null)

const useQuestion = () => {
  const context = useContext(QuestionContext)

  if (!context) {
    throw new Error("Question components must be used within Question")
  }

  return context
}

export type QuestionProps = Omit<
  ComponentProps<"form">,
  "defaultValue" | "onSubmit" | "value"
> & {
  defaultValue?: QuestionValue
  disabled?: boolean
  onSubmit?: (
    response: QuestionResponse,
    event: FormEvent<HTMLFormElement>
  ) => void | Promise<void>
  onValueChange?: (value: QuestionValue) => void
  selectionMode?: SelectionMode
  value?: QuestionValue
}

const EMPTY_VALUE: QuestionValue = { selectedValues: [], text: "" }

const getSelectedValues = (
  currentValues: readonly string[],
  optionValue: string,
  selectionMode: SelectionMode
): readonly string[] => {
  const isSelected = currentValues.includes(optionValue)

  if (selectionMode === "single") {
    return isSelected ? [] : [optionValue]
  }

  if (isSelected) {
    return currentValues.filter((item) => item !== optionValue)
  }

  return [...currentValues, optionValue]
}

export const Question = ({
  children,
  className,
  defaultValue = EMPTY_VALUE,
  disabled = false,
  onSubmit,
  onValueChange,
  selectionMode = "single",
  value: controlledValue,
  ...props
}: QuestionProps) => {
  const [internalValue, setInternalValue] = useState(defaultValue)
  const value = controlledValue ?? internalValue

  const setValue = useCallback(
    (nextValue: QuestionValue) => {
      if (controlledValue === undefined) {
        setInternalValue(nextValue)
      }
      onValueChange?.(nextValue)
    },
    [controlledValue, onValueChange]
  )

  const setText = useCallback(
    (text: string) => {
      setValue({ ...value, text })
    },
    [setValue, value]
  )

  const toggleValue = useCallback(
    (optionValue: string) => {
      const selectedValues = getSelectedValues(
        value.selectedValues,
        optionValue,
        selectionMode
      )
      setValue({ ...value, selectedValues })
    },
    [selectionMode, setValue, value]
  )

  const contextValue = useMemo(
    () => ({
      disabled,
      selectedValues: value.selectedValues,
      selectionMode,
      setText,
      text: value.text,
      toggleValue,
    }),
    [disabled, selectionMode, setText, toggleValue, value]
  )

  const handleSubmit = useCallback(
    async (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      if (disabled) {
        return
      }

      const text = value.text.trim()
      if (value.selectedValues.length === 0 && text.length === 0) {
        return
      }

      await onSubmit?.(
        {
          selectedValues: value.selectedValues,
          text: text.length > 0 ? text : undefined,
        },
        event
      )
    },
    [disabled, onSubmit, value]
  )

  return (
    <QuestionContext.Provider value={contextValue}>
      <form
        className={cn(
          "bg-background space-y-4 rounded-lg border p-4",
          className
        )}
        onSubmit={handleSubmit}
        {...props}
      >
        {children}
      </form>
    </QuestionContext.Provider>
  )
}

export type QuestionPromptProps = HTMLAttributes<HTMLParagraphElement>

export const QuestionPrompt = ({
  className,
  ...props
}: QuestionPromptProps) => (
  <p className={cn("text-sm font-medium", className)} {...props} />
)

export type QuestionDescriptionProps = HTMLAttributes<HTMLParagraphElement>

export const QuestionDescription = ({
  className,
  ...props
}: QuestionDescriptionProps) => (
  <p className={cn("text-muted-foreground text-sm", className)} {...props} />
)

export type QuestionOptionsProps = HTMLAttributes<HTMLDivElement>

export const QuestionOptions = ({
  className,
  ...props
}: QuestionOptionsProps) => {
  const { selectionMode } = useQuestion()

  return (
    <div
      className={cn("flex flex-wrap gap-2", className)}
      role={selectionMode === "single" ? "radiogroup" : "group"}
      {...props}
    />
  )
}

export type QuestionOptionProps = Omit<
  ComponentProps<typeof Button>,
  "value"
> & {
  value: string
}

export const QuestionOption = ({
  children,
  className,
  disabled,
  onClick,
  value,
  variant,
  ...props
}: QuestionOptionProps) => {
  const question = useQuestion()
  const isSelected = question.selectedValues.includes(value)
  const role = question.selectionMode === "single" ? "radio" : "checkbox"
  const handleClick = useCallback(
    (event: MouseEvent<HTMLButtonElement>) => {
      question.toggleValue(value)
      onClick?.(event)
    },
    [onClick, question, value]
  )

  return (
    <Button
      aria-checked={isSelected}
      className={cn("h-auto whitespace-normal", className)}
      disabled={question.disabled || disabled}
      onClick={handleClick}
      role={role}
      type="button"
      variant={variant ?? (isSelected ? "default" : "outline")}
      {...props}
    >
      {children ?? value}
    </Button>
  )
}

export type QuestionInputProps = Omit<
  ComponentProps<typeof Textarea>,
  "defaultValue" | "value"
>

export const QuestionInput = ({
  className,
  disabled,
  onChange,
  ...props
}: QuestionInputProps) => {
  const question = useQuestion()
  const handleChange = useCallback(
    (event: ChangeEvent<HTMLTextAreaElement>) => {
      question.setText(event.currentTarget.value)
      onChange?.(event)
    },
    [onChange, question]
  )

  return (
    <Textarea
      className={cn("min-h-20", className)}
      disabled={question.disabled || disabled}
      onChange={handleChange}
      value={question.text}
      {...props}
    />
  )
}

export type QuestionActionsProps = HTMLAttributes<HTMLDivElement>

export const QuestionActions = ({
  className,
  ...props
}: QuestionActionsProps) => (
  <div
    className={cn("flex items-center justify-end gap-2", className)}
    {...props}
  />
)

export type QuestionSubmitProps = ComponentProps<typeof Button> & {
  children?: ReactNode
}

export const QuestionSubmit = ({
  children = "Submit",
  disabled,
  ...props
}: QuestionSubmitProps) => {
  const question = useQuestion()
  const hasResponse =
    question.selectedValues.length > 0 || question.text.trim().length > 0

  return (
    <Button
      disabled={question.disabled || disabled || !hasResponse}
      type="submit"
      {...props}
    >
      {children}
    </Button>
  )
}

import { cn } from "@/lib/utils"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot as SlotPrimitive } from "radix-ui"
import * as React from "react"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? SlotPrimitive.Slot : "button"

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function getSitePathname(
  pathname: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH || ""
) {
  const base = basePath.replace(/\/+$/, "")
  const path =
    pathname === base || pathname.startsWith(`${base}/`)
      ? pathname.slice(base.length)
      : pathname
  return path.replace(/\/+$/, "") || "/"
}

/**
 * Get the base URL depending on the current environment
 */
export function getBaseUrl() {
  const basePath = (process.env.NEXT_PUBLIC_BASE_PATH || "").replace(/\/$/, "")
  const withBasePath = (url: string) => {
    const base = url.replace(/\/$/, "")
    return basePath && !base.endsWith(basePath) ? `${base}${basePath}` : base
  }
  // For server-side rendering, we need to use environment variables
  if (typeof window === "undefined") {
    // Check for Vercel-specific environment variables
    // Production URL takes precedence if available (works in all environments)
    if (process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL) {
      return withBasePath(
        `https://${process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL}`
      )
    }

    // For branch deployments
    if (process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL) {
      return withBasePath(
        `https://${process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL}`
      )
    }

    // For regular deployments
    if (process.env.NEXT_PUBLIC_VERCEL_URL) {
      return withBasePath(`https://${process.env.NEXT_PUBLIC_VERCEL_URL}`)
    }

    // Legacy support
    if (process.env.VERCEL_URL) {
      return withBasePath(`https://${process.env.VERCEL_URL}`)
    }

    // Fall back to explicitly set environment variables
    if (process.env.NEXT_PUBLIC_BASE_URL) {
      return withBasePath(process.env.NEXT_PUBLIC_BASE_URL)
    }

    // Default for development - check PORT env var first
    const port = process.env.PORT || 3000
    return withBasePath(
      process.env.NODE_ENV === "development" ? `http://localhost:${port}` : ""
    )
  }

  // For client-side, we can just use the browser's location
  return withBasePath(window.location.origin)
}

import { cn } from "@/lib/utils"
import * as React from "react"

function Textarea({ className, ...props }: React.ComponentProps<"textarea">) {
  return (
    <textarea
      data-slot="textarea"
      className={cn(
        "border-input placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:bg-input/30 flex field-sizing-content min-h-16 w-full rounded-md border bg-transparent px-3 py-2 text-base shadow-xs transition-[color,box-shadow] outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
        className
      )}
      {...props}
    />
  )
}

export { Textarea }
